from datetime import datetime
from dataclasses import dataclass

@dataclass
class Event:
    name: str
    timestamp: datetime
    source: str

    # Instance method — needs instance state
    def age_seconds(self) -> float:
        return (datetime.now() - self.timestamp).total_seconds()

    # Class method — factory / alternative constructor
    @classmethod
    def from_dict(cls, data: dict) -> 'Event':
        return cls(
            name=data['name'],
            timestamp=datetime.fromisoformat(data['ts']),
            source=data.get('source', 'unknown')
        )  # uses cls, not Event — works correctly in subclasses

    # Class method — another factory
    @classmethod
    def now(cls, name: str, source: str = 'system') -> 'Event':
        return cls(name=name, timestamp=datetime.now(), source=source)

    # Static method — utility, no self/cls needed
    @staticmethod
    def is_valid_name(name: str) -> bool:
        return bool(name) and len(name) <= 100

# Usage
e1 = Event.from_dict({'name': 'login', 'ts': '2024-01-15T10:30:00'})
e2 = Event.now('purchase')
print(Event.is_valid_name('login'))  # True — no instance needed

class AuditEvent(Event):
    pass

# classmethod respects inheritance — creates AuditEvent, not Event
ae = AuditEvent.from_dict({'name': 'audit', 'ts': '2024-01-15T10:30:00'})
print(type(ae))  # <class 'AuditEvent'>

# BAD: inheritance for code reuse
class Animal:
    def speak(self): ...
    def serialize(self): ...
    def validate(self): ...
    def log_action(self, action): ...

class Dog(Animal):  # inherits unrelated serialization + logging concerns
    pass

# GOOD: composition
class Logger:
    def log(self, msg: str): print(f'[LOG] {msg}')

class Serializer:
    def to_json(self, obj) -> str:
        import json
        return json.dumps(obj.__dict__)

class Dog:
    def __init__(self, name: str):
        self.name = name
        self._logger = Logger()           # composed in
        self._serializer = Serializer()   # composed in

    def speak(self) -> str:
        self._logger.log(f'{self.name} spoke')
        return 'Woof!'

    def to_json(self) -> str:
        return self._serializer.to_json(self)

# GOOD: Protocol for duck typing (Python 3.8+)
from typing import Protocol

class Readable(Protocol):
    def read(self) -> str: ...

def process(source: Readable) -> str:
    return source.read()  # any object with .read() works — no inheritance needed

# Mixins — inheritance done composably
class JSONMixin:
    def to_json(self) -> str:
        import json
        return json.dumps(self.__dict__)

class TimestampMixin:
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        from datetime import datetime
        self.created_at = datetime.now()

class Event(JSONMixin, TimestampMixin):
    def __init__(self, name: str):
        super().__init__()
        self.name = name
